  "law_record": {
    "id": "NRS-484B-217-2",
    "title": "Zones in which overtaking on left side or making left-hand turn prohibited (2)",
    "text": "Except as otherwise provided in subsections 3 and 4, a driver shall not drive on the left side of the highway within such zone or drive across or on the left side of any pavement striping designed to mark such zone throughout its length. A driver may drive across a pavement striping marking such zone to an adjoining highway if the driver has first given the appropriate turn signal and there will be no impediment to oncoming or following traffic. Except where otherwise provided, a driver may drive across a pavement striping marking such a zone to make a left-hand turn if the driver has first given the appropriate turn signal in compliance with NRS 484B.413 [NRS-484B-413-2], if it is safe and if it would not be an impediment to oncoming or following traffic.",
    "source": "NRS 484B.217(2); with 484B.217(3), 484B.217(4)"
  },
  "summary": {
    "activation_conditions": [
      "the subject is within a marked no-passing zone",
      "the subject drives left of centre, or crosses the zone striping"
    ],
    "exceptions": [
      "crossing the striping to an adjoining highway, after the appropriate turn signal, with no impediment to oncoming or following traffic",
      "crossing the striping to make a left turn, after the signal required by the turn-signal rule, if it is safe and no impediment to oncoming or following traffic"
    ],
    "id": "NRS-484B-217-2",
    "residue": [
      "'safe' and 'impediment' are judgement elements needing declared bounds"
    ],
    "source": "NRS 484B.217(2); with 484B.217(3), 484B.217(4)",
    "subject": "driver",
    "theme": "overtaking",
    "tier": "Q",
    "timing_requirements": [
